import { demoDashboard } from "@/lib/demo-data";
import { demoStore } from "@/lib/demo-properties";
import { apiBaseUrl, forwardJson, routeError, upstream } from "@/lib/server-api";

export async function GET() {
  try {
    if (!apiBaseUrl) return Response.json({ success: true, message: "Preview dashboard", data: { ...demoDashboard, totalProperties: demoStore.properties.length, publishedProperties: demoStore.properties.filter((property) => property.status === "PUBLISHED").length } });
    return forwardJson(await upstream("/api/v1/property-owners/me/dashboard"));
  } catch (error) {
    return routeError(error);
  }
}
